"""Gene-Ontology concepts, the reference construction of COMET on Tabula Muris.

EDITABLE concept construction -- see custom_template.py for the contract.
"""
from __future__ import annotations

import numpy as np


def build_concepts(genes, go_annotations_path, go_obo_path, train_X, train_y, val_X, val_y,
                   max_concepts, seed):
    """Gene Ontology terms as concepts (upstream get_go2gene defaults), random subset under a budget."""
    concepts = go_term_concepts(genes, go_annotations_path, go_obo_path)
    if len(concepts) > max_concepts:
        rng = np.random.RandomState(seed)
        keep = sorted(rng.choice(len(concepts), size=max_concepts, replace=False).tolist())
        concepts = [concepts[i] for i in keep]
    return concepts


# ---- verbatim port of upstream TM/data/map_GO.py + TM/data/dataset.py::create_go_mask ----
def _map_mgi2go(filepath):
    """upstream map_GO.py::map_mgi2go (the evidence-code filter is commented out upstream)."""
    from collections import defaultdict
    mgi2go = defaultdict(set)
    with open(filepath) as f:
        for line in f.readlines():
            if line[0] != '!':
                line = line.split("	")
                mgi2go[line[2]].add(line[4])
    return mgi2go


def _check_conditions(GOterm, num_genes, min_genes, max_genes, min_level, max_level):
    """upstream map_GO.py::check_conditions (its second test is `level > min_level`, so only
    terms at exactly `min_level` survive)."""
    if min_genes is not None and num_genes < min_genes:
        return False
    if max_genes is not None and num_genes > max_genes:
        return False
    if min_level is not None and GOterm.level < min_level:
        return False
    if min_level is not None and GOterm.level > min_level:
        return False
    return True


def go_term_concepts(genes, go_annotations_path, go_obo_path, GO_min_genes=32, GO_max_genes=None,
                     GO_min_level=6, GO_max_level=1):
    """upstream dataset.py::load_tabular_muris -> get_go2gene(GO_min_genes=32, GO_min_level=6) ->
    create_go_mask: GO terms (sorted by id) as sorted gene-index lists."""
    from collections import defaultdict
    from goatools import obo_parser
    gene_set = set(genes)
    mgi2go = _map_mgi2go(go_annotations_path)
    GOdag = obo_parser.GODag(obo_file=go_obo_path, prt=None)
    gene2go = {g: {go for go in mgi2go[g] if go in GOdag} for g in mgi2go if g in gene_set}
    GOdag.update_association(gene2go)          # propagate through the hierarchy
    go2gene = defaultdict(set)
    for g, gos in gene2go.items():
        for go in gos:
            go2gene[go].add(g)
    kept = {}
    for go, gs in go2gene.items():
        term = GOdag.get(go)
        if term is not None and _check_conditions(term, len(gs), GO_min_genes, GO_max_genes, GO_min_level, GO_max_level):
            kept[go] = gs
    gene2index = {g: i for i, g in enumerate(genes)}
    return [sorted(gene2index[g] for g in kept[go]) for go in sorted(kept)]

