Epsilon Prediction.content:
def compute_training_target(x_0, noise, timesteps, schedule):
    # Epsilon prediction: model learns to predict the added noise
    return noise


def predict_x0(model_output, x_t, timesteps, schedule):
    # Recover x_0 from epsilon prediction:
    # x_t = sqrt(alpha) * x_0 + sqrt(1-alpha) * eps
    # => x_0 = (x_t - sqrt(1-alpha) * eps) / sqrt(alpha)
    sqrt_alpha = schedule["sqrt_alpha"][timesteps].view(-1, 1, 1, 1)
    sqrt_one_minus_alpha = schedule["sqrt_one_minus_alpha"][timesteps].view(-1, 1, 1, 1)
    return (x_t - sqrt_one_minus_alpha * model_output) / sqrt_alpha.clamp(min=1e-8)

X0 Prediction.content:
def compute_training_target(x_0, noise, timesteps, schedule):
    # SNR-scaled X0: predict sqrt(alpha) * x_0
    # This balances loss across timesteps — high noise has small target
    sqrt_alpha = schedule["sqrt_alpha"][timesteps].view(-1, 1, 1, 1)
    return sqrt_alpha * x_0


def predict_x0(model_output, x_t, timesteps, schedule):
    # Recover x_0 from SNR-scaled prediction:
    # model predicts sqrt(alpha) * x_0 => x_0 = output / sqrt(alpha)
    sqrt_alpha = schedule["sqrt_alpha"][timesteps].view(-1, 1, 1, 1)
    return model_output / sqrt_alpha.clamp(min=1e-8)

Uncertainty Weighting.content:
class MultiTaskLoss(nn.Module):
    """Uncertainty weighting (Kendall et al., 2018).

    Learns per-task log-variance: loss_i / exp(log_var_i) + log_var_i.
    """

    def __init__(self, num_tasks=2):
        super().__init__()
        self.log_vars = nn.Parameter(torch.zeros(num_tasks))

    def forward(self, fine_loss, coarse_loss, epoch, total_epochs):
        losses = [fine_loss, coarse_loss]
        total = sum(
            torch.exp(-self.log_vars[i]) * losses[i] + self.log_vars[i]
            for i in range(2)
        )
        return total

DWA.content:
class MultiTaskLoss(nn.Module):
    """Dynamic Weight Average (Liu et al., 2019).

    Weights tasks by relative loss change rate with temperature.
    """

    def __init__(self, num_tasks=2):
        super().__init__()
        self.prev_losses = None
        self.T = 2.0  # temperature

    def forward(self, fine_loss, coarse_loss, epoch, total_epochs):
        losses = torch.stack([fine_loss, coarse_loss])
        if self.prev_losses is None or epoch == 0:
            weights = torch.ones(2, device=losses.device)
        else:
            ratios = losses.detach() / (self.prev_losses + 1e-8)
            weights = 2 * F.softmax(ratios / self.T, dim=0)
        self.prev_losses = losses.detach().clone()
        return (weights * losses).sum()

