def get_lr(epoch, total_epochs, base_lr, config):
    """Cosine annealing from base_lr to 0.

    LR = base_lr * 0.5 * (1 + cos(pi * epoch / total_epochs))
    """
    return base_lr * 0.5 * (1 + math.cos(math.pi * epoch / total_epochs))

WarmupCosine.content:
def get_lr(epoch, total_epochs, base_lr, config):
    """Linear warmup (5 epochs) then cosine decay to 0.

    Epochs 0-4: linearly ramp from base_lr/5 to base_lr.
    Epochs 5+: cosine anneal from base_lr to 0.
    """
    warmup = 5
    if epoch < warmup:
        return base_lr * (epoch + 1) / warmup
    progress = (epoch - warmup) / (total_epochs - warmup)
    return base_lr * 0.5 * (1 + math.cos(math.pi * progress))

GroupNorm.content:
class CustomNorm(nn.Module):
    """Group Normalization for 2D feature maps. Drop-in replacement for BatchNorm2d.

    Divides channels into groups and normalizes within each group independently.
    Works well with small batch sizes where BatchNorm statistics are noisy.

    Reference: Wu & He, "Group Normalization" (ECCV 2018)
    """

    def __init__(self, num_features):
        super().__init__()
        num_groups = min(32, num_features)
        # Ensure num_features is divisible by num_groups
        while num_features % num_groups != 0:
            num_groups -= 1
        self.norm = nn.GroupNorm(num_groups, num_features)

    def forward(self, x):
        return self.norm(x)

Stochastic Depth.content:
class CustomBlock(nn.Module):
    """Residual block with stochastic depth (Huang et al., 2016).

    During training, each block's residual branch is randomly dropped with
    probability (1 - survival_prob). The survival probability linearly decays
    from 1.0 (first block) to p_L (last block). At test time, the residual
    output is deterministically scaled by the survival probability.
    """
    expansion = 1
    _block_counter = 0
    _p_last = 0.5  # survival prob of the deepest block

    def __init__(self, in_planes, planes, stride=1):
        super().__init__()
        self.conv1 = nn.Conv2d(in_planes, planes, 3, stride=stride, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(planes)
        self.conv2 = nn.Conv2d(planes, planes, 3, padding=1, bias=False)
        self.bn2 = nn.BatchNorm2d(planes)
        self.shortcut = nn.Sequential()
        if stride != 1 or in_planes != planes * self.expansion:
            self.shortcut = nn.Sequential(
                nn.Conv2d(in_planes, planes * self.expansion, 1, stride=stride, bias=False),
                nn.BatchNorm2d(planes * self.expansion),
            )
        # Reset counter when first block of a new model is created
        # (CIFAR ResNets always start layer1 with in_planes=16, planes=16, stride=1)
        if in_planes == 16 and planes == 16 and stride == 1:
            CustomBlock._block_counter = 0
        CustomBlock._block_counter += 1
        self.block_idx = CustomBlock._block_counter

    def forward(self, x):
        shortcut = self.shortcut(x)
        L = CustomBlock._block_counter
        p = 1.0 - (self.block_idx / L) * (1.0 - CustomBlock._p_last)
        if self.training:
            if torch.rand(1).item() < p:
                out = F.relu(self.bn1(self.conv1(x)))
                out = self.bn2(self.conv2(out))
                return F.relu(out + shortcut)
            else:
                return F.relu(shortcut)
        else:
            out = F.relu(self.bn1(self.conv1(x)))
            out = self.bn2(self.conv2(out))
            return F.relu(p * out + shortcut)

Kaiming Normal.content:
def initialize_weights(model, config):
    """Kaiming/He normal initialization (fan_out, ReLU).

    Conv2d: N(0, sqrt(2/fan_out)) — preserves forward-pass variance with ReLU.
    BatchNorm2d: weight=1, bias=0.
    Linear: N(0, sqrt(2/fan_in)).
    """
    for m in model.modules():
        if isinstance(m, nn.Conv2d):
            nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
        elif isinstance(m, nn.BatchNorm2d):
            nn.init.constant_(m.weight, 1)
            nn.init.constant_(m.bias, 0)
        elif isinstance(m, nn.Linear):
            nn.init.kaiming_normal_(m.weight, mode='fan_in', nonlinearity='relu')
            if m.bias is not None:
                nn.init.constant_(m.bias, 0)

Orthogonal.content:
def initialize_weights(model, config):
    """Orthogonal initialization.

    Conv2d & Linear: orthogonal matrix (gain=sqrt(2) for ReLU).
    BatchNorm2d: weight=1, bias=0.
    """
    gain = nn.init.calculate_gain('relu')
    for m in model.modules():
        if isinstance(m, nn.Conv2d):
            nn.init.orthogonal_(m.weight, gain=gain)
        elif isinstance(m, nn.BatchNorm2d):
            nn.init.constant_(m.weight, 1)
            nn.init.constant_(m.bias, 0)
        elif isinstance(m, nn.Linear):
            nn.init.orthogonal_(m.weight, gain=gain)
            if m.bias is not None:
                nn.init.constant_(m.bias, 0)

