class CollapseMetric:
    """Quadric error metric with boundary / sharp-crease constraint planes."""

    BOUNDARY_WEIGHT = 1000.0
    CREASE_DEG = 60.0

    def __init__(self, V: np.ndarray, F: np.ndarray) -> None:
        self.Q = _accumulate_quadrics(V, F, weight="area")
        self._add_constraint_planes(V, F)

    def _add_constraint_planes(self, V, F):
        plane, ok, area = _face_planes(V, F)
        E = np.vstack([F[:, [0, 1]], F[:, [1, 2]], F[:, [2, 0]]])
        owner = np.tile(np.arange(F.shape[0]), 3)
        key = np.sort(E, axis=1)
        order = np.lexsort((key[:, 1], key[:, 0]))
        key, owner = key[order], owner[order]
        i = 0
        constraints = []
        while i < key.shape[0]:
            j = i + 1
            while j < key.shape[0] and key[j, 0] == key[i, 0] and key[j, 1] == key[i, 1]:
                j += 1
            count = j - i
            sharp = False
            if count == 1:
                sharp = True
            elif count == 2:
                n0, n1 = plane[owner[i], :3], plane[owner[i + 1], :3]
                cos = float(np.clip(np.dot(n0, n1), -1.0, 1.0))
                sharp = np.degrees(np.arccos(cos)) > self.CREASE_DEG
            if sharp:
                a, b = int(key[i, 0]), int(key[i, 1])
                e = V[b] - V[a]
                nrm = np.cross(e, plane[owner[i], :3])
                ln = float(np.linalg.norm(nrm))
                if ln > 1e-18:
                    nrm = nrm / ln
                    d = -float(np.dot(nrm, V[a]))
                    constraints.append((a, b, np.array([nrm[0], nrm[1], nrm[2], d])))
            i = j
        for a, b, pl in constraints:
            K = self.BOUNDARY_WEIGHT * np.outer(pl, pl)
            self.Q[a] += K
            self.Q[b] += K

    def edge_cost(self, i: int, j: int, V: np.ndarray):
        return _qem_cost(self.Q[i] + self.Q[j], V[i], V[j])

    def merge(self, i: int, j: int) -> None:
        self.Q[i] = self.Q[i] + self.Q[j]


def _face_planes(V, F):
    p0, p1, p2 = V[F[:, 0]], V[F[:, 1]], V[F[:, 2]]
    nrm = np.cross(p1 - p0, p2 - p0)
    ln = np.linalg.norm(nrm, axis=1, keepdims=True)
    ok = ln[:, 0] > 1e-18
    unit = np.where(ln > 1e-18, nrm / np.where(ln > 1e-18, ln, 1.0), 0.0)
    d = -np.einsum("ij,ij->i", unit, p0)
    return np.concatenate([unit, d[:, None]], axis=1), ok, 0.5 * ln[:, 0]


def _accumulate_quadrics(V, F, weight="none"):
    Q = np.zeros((V.shape[0], 4, 4), dtype=np.float64)
    plane, ok, area = _face_planes(V, F)
    Kp = plane[:, :, None] * plane[:, None, :]
    if weight == "area":
        Kp = Kp * area[:, None, None]
    for k in range(3):
        np.add.at(Q, F[ok, k], Kp[ok])
    return Q


def _qem_cost(Q, pi, pj):
    A, b = Q[:3, :3], -Q[:3, 3]
