def geodesic_distances(V: np.ndarray, F: np.ndarray, sources: np.ndarray) -> np.ndarray:
    """Dijkstra on the edge graph enriched with two-ring chords."""
    import heapq
    n = V.shape[0]
    ring = [set() for _ in range(n)]
    for tri in F:
        a, b, c = int(tri[0]), int(tri[1]), int(tri[2])
        ring[a].update((b, c)); ring[b].update((a, c)); ring[c].update((a, b))
    pairs = set()
    for i in range(n):
        one = ring[i]
        for j in one:
            pairs.add((min(i, j), max(i, j)))
            for k in ring[j]:
                if k != i:
                    pairs.add((min(i, k), max(i, k)))
    P = np.asarray(sorted(pairs), dtype=np.int64)
    W = np.linalg.norm(V[P[:, 0]] - V[P[:, 1]], axis=1)
    adj = [[] for _ in range(n)]
    for (a, b), wt in zip(P, W):
        adj[int(a)].append((int(b), float(wt)))
        adj[int(b)].append((int(a), float(wt)))
    dist = np.full(n, np.inf)
    heap = []
    for s in np.asarray(sources).reshape(-1):
        dist[int(s)] = 0.0
        heapq.heappush(heap, (0.0, int(s)))
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, wt in adj[u]:
            nd = d + wt
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    dist[~np.isfinite(dist)] = 0.0
    return dist

uniform.content:
def estimate_vertex_normals(V: np.ndarray, F: np.ndarray) -> np.ndarray:
    """Unweighted mean of the incident face normals."""
    fn = face_normals(V, F)
    N = np.zeros_like(V)
    for k in range(3):
        np.add.at(N, F[:, k], fn)
    ln = np.linalg.norm(N, axis=1, keepdims=True)
    return np.where(ln > 1e-18, N / np.where(ln > 1e-18, ln, 1.0), 0.0)

area.content:
def estimate_vertex_normals(V: np.ndarray, F: np.ndarray) -> np.ndarray:
    """Face normals weighted by triangle area."""
    fn = face_normals(V, F)
    w = face_areas(V, F)
    N = np.zeros_like(V)
    for k in range(3):
        np.add.at(N, F[:, k], fn * w[:, None])
    ln = np.linalg.norm(N, axis=1, keepdims=True)
    return np.where(ln > 1e-18, N / np.where(ln > 1e-18, ln, 1.0), 0.0)

