split_only.content:
def remesh_round(V: np.ndarray, F: np.ndarray, target_len: float):
    """Split edges longer than 4/3 * target at their midpoint."""
    V = V.copy()
    F = F.copy()

    def edges_of(F):
        E = np.vstack([F[:, [0, 1]], F[:, [1, 2]], F[:, [2, 0]]])
        return np.unique(np.sort(E, axis=1), axis=0)

    for _ in range(4):
        E = edges_of(F)
        L = np.linalg.norm(V[E[:, 0]] - V[E[:, 1]], axis=1)
        long = E[L > 4.0 / 3.0 * target_len]
        if len(long) == 0:
            break
        mid = 0.5 * (V[long[:, 0]] + V[long[:, 1]])
        base = V.shape[0]
        V = np.vstack([V, mid])
        mid_id = {(int(a), int(b)): base + i for i, (a, b) in enumerate(long)}

        def midpoint_of(x, y):
            return mid_id.get((min(x, y), max(x, y)))

        newF = []
        for tri in F:
            a, b, c = int(tri[0]), int(tri[1]), int(tri[2])
            m_ab, m_bc, m_ca = midpoint_of(a, b), midpoint_of(b, c), midpoint_of(c, a)
            n_marked = (m_ab is not None) + (m_bc is not None) + (m_ca is not None)
            if n_marked == 0:
                newF.append((a, b, c))
            elif n_marked == 1:
                # bisect the one marked edge, connect its midpoint to the
                # opposite vertex -- the only edge in this triangle affected,
                # so no neighbouring T-junction is introduced by this face.
                if m_ab is not None:
                    newF += [(a, m_ab, c), (m_ab, b, c)]
                elif m_bc is not None:
                    newF += [(b, m_bc, a), (m_bc, c, a)]
                else:
                    newF += [(c, m_ca, b), (m_ca, a, b)]
            elif n_marked == 2:
                # bisect both marked edges (1-to-3 split); every marked edge
                # of this face is actually split, so adjacent faces sharing
                # either marked edge stay conforming.
                if m_ab is None:
                    newF += [(b, m_bc, m_ca), (m_bc, c, m_ca), (a, b, m_ca)]
                elif m_bc is None:
                    newF += [(c, m_ca, m_ab), (m_ca, a, m_ab), (b, c, m_ab)]
                else:
                    newF += [(a, m_ab, m_bc), (m_ab, b, m_bc), (c, a, m_bc)]
            else:
                # all three edges marked: uniform 1-to-4 split.
                newF += [(a, m_ab, m_ca), (m_ab, b, m_bc), (m_ca, m_bc, c),
                         (m_ab, m_bc, m_ca)]
        F = np.asarray(newF, dtype=np.int32)
    return V, F

loop.content:
def subdivision_rules(V, F, E, EV, VE, EF):
    """Loop (1987) subdivision."""
    n = V.shape[0]
    even = V.copy()
    is_boundary_v = np.zeros(n, dtype=bool)

    boundary_edge = (EF[:, 0] < 0) | (EF[:, 1] < 0)
    for e in np.nonzero(boundary_edge)[0]:
        is_boundary_v[E[e, 0]] = True
        is_boundary_v[E[e, 1]] = True

    for i in range(n):
        ring = EV[i]
        k = len(ring)
        if k == 0:
            continue
        if is_boundary_v[i]:
            b = [e for e in VE[i] if boundary_edge[e]]
            if len(b) == 2:
                a, c = (E[b[0]][E[b[0]] != i][0], E[b[1]][E[b[1]] != i][0])
                even[i] = 0.75 * V[i] + 0.125 * (V[a] + V[c])
            continue
        if k == 3:
            beta = 3.0 / 16.0
        else:
            beta = (5.0 / 8.0 - (3.0 / 8.0 + 0.25 * np.cos(2 * np.pi / k)) ** 2) / k
        even[i] = (1.0 - k * beta) * V[i] + beta * V[ring].sum(axis=0)

    odd = np.zeros((E.shape[0], 3))
    for e, (a, b) in enumerate(E):
        if boundary_edge[e]:
            odd[e] = 0.5 * (V[a] + V[b])
            continue
        opp = []
        for f in EF[e]:
            tri = F[f]
            opp.append(int(tri[(tri != a) & (tri != b)][0]))
        odd[e] = 0.375 * (V[a] + V[b]) + 0.125 * (V[opp[0]] + V[opp[1]])
    return even, odd

