wavelet.content:
def denoise(img: np.ndarray, sigma: float) -> np.ndarray:
    """BayesShrink soft-thresholding in a critically-sampled (decimated) wavelet basis."""
    import pywt

    def shrink(channel):
        coeffs = pywt.wavedec2(channel, "db4", level=3, mode="periodization")
        out = [coeffs[0]]
        for level in coeffs[1:]:
            new_d = []
            for band in level:
                sigma_y = np.median(np.abs(band)) / 0.6745
                sigma_x = np.sqrt(max(sigma_y ** 2 - sigma ** 2, 1e-12))
                thr = sigma ** 2 / max(sigma_x, 1e-12)
                new_d.append(np.sign(band) * np.maximum(np.abs(band) - thr, 0.0))
            out.append(tuple(new_d))
        return pywt.waverec2(out, "db4", mode="periodization")[:channel.shape[0],
                                                                 :channel.shape[1]]

    out = np.empty_like(img)
    for c in range(3):
        out[..., c] = shrink(img[..., c])
    return np.clip(out, 0.0, 1.0)

