trunc_exp.content:
def make_density_head(geo_feat_dim: int):
    """Truncated-exponential density head (instant-NGP / torch-ngp trunc_exp)."""
    import torch
    import torch.nn as nn
    from torch.autograd import Function
    from torch.cuda.amp import custom_bwd, custom_fwd

    class _TruncExp(Function):
        @staticmethod
        @custom_fwd(cast_inputs=torch.float32)
        def forward(ctx, x):
            ctx.save_for_backward(x)
            return torch.exp(x)

        @staticmethod
        @custom_bwd
        def backward(ctx, g):
            (x,) = ctx.saved_tensors
            return g * torch.exp(torch.clamp(x, max=15))

    trunc_exp = _TruncExp.apply

    class Head(nn.Module):
        def __init__(self, d):
            super().__init__()
            self.net = nn.Linear(d, 1)

        def forward(self, feat):
            return trunc_exp(self.net(feat) - 1.0)

    return Head(geo_feat_dim)

