def make_density_head(geo_feat_dim: int):
    """Softplus with a learnable scale."""
    import torch
    import torch.nn as nn
    import torch.nn.functional as F

    class Head(nn.Module):
        def __init__(self, d):
            super().__init__()
            self.net = nn.Linear(d, 1)
            self.scale = nn.Parameter(torch.ones(1))

        def forward(self, feat):
            return F.softplus(self.scale * self.net(feat) - 1.0)

    return Head(geo_feat_dim)

