class Component(DefaultComponent):
    def light_selection_pdf(self, lights, si_p, si_n, rng):
        """Sample proportional to power / d^2 from the shading point."""
        # the driver shares one distribution per bounce, so use the centroid of the
        # shading points (or the box centre when no position is given)
        if si_p is None:
            ref = np.array([0.5, 0.5, 0.5])
        else:
            ref = 0.5 * (np.asarray(si_p).min(axis=0) + np.asarray(si_p).max(axis=0))
        w = []
        for l in lights:
            d2 = max(float(np.sum((l.center - ref) ** 2)), 1e-4)
            w.append(l.radiance.mean() * l.area / d2)
        w = np.asarray(w)
        return w / w.sum()

