        w = dr.select(bsdf_pdf < self.CUTOFF * big, 0.0, bsdf_pdf)
        wl = dr.select(emitter_pdf < self.CUTOFF * big, 0.0, emitter_pdf)
        return w / (w + wl)

    def mis_light_weight(self, bsdf_pdf, emitter_pdf):
        big = dr.maximum(bsdf_pdf, emitter_pdf)
        w = dr.select(bsdf_pdf < self.CUTOFF * big, 0.0, bsdf_pdf)
        wl = dr.select(emitter_pdf < self.CUTOFF * big, 0.0, emitter_pdf)
        return wl / (w + wl)

