class Component(DefaultComponent):
    def rr_survival(self, throughput, depth, sampler):
        # floor q above 0: an unclamped max(throughput) of exactly 0 makes
        # rcp(q) = inf, and the rare lane where a near-zero-but-positive q
        # DOES survive would otherwise get its unbiasing boost silently
        # zeroed out by the isfinite safety net downstream -- a real energy
        # loss, not just a masked-out dead path.
        q = dr.maximum(dr.minimum(dr.max(throughput), 0.95), 1e-4)
        survive = sampler.next_1d() < q
        return survive, dr.rcp(q)

