class Component(DefaultComponent):
    def rr_survival(self, throughput, depth, sampler):
        # see throughput.edit.py: floor q above 0 so rcp(q) stays finite and
        # a surviving near-zero-throughput lane keeps its unbiasing boost
        # instead of having it zeroed out by the isfinite safety net.
        q = dr.maximum(dr.minimum(dr.max(throughput), 0.95), 1e-4)
        apply = mi.UInt32(depth) >= 3
        q = dr.select(apply, q, 1.0)
        survive = sampler.next_1d() < q
        return survive, dr.rcp(q)

