def make_stress(P):
    """Neo-Hookean with the log(J) volumetric term."""
    import taichi as ti

    @ti.func
    def stress(F_p):
        J = ti.max(F_p.determinant(), 0.01)
        return P.mu * (F_p @ F_p.transpose() - ti.Matrix.identity(ti.f32, 3))             + P.lam * ti.log(J) * ti.Matrix.identity(ti.f32, 3)

    return stress

