def make_stress(P):
    """St. Venant-Kirchhoff."""
    import taichi as ti

    @ti.func
    def stress(F_p):
        E = 0.5 * (F_p.transpose() @ F_p - ti.Matrix.identity(ti.f32, 3))
        trE = E[0, 0] + E[1, 1] + E[2, 2]
        return F_p @ (2.0 * P.mu * E + P.lam * trE * ti.Matrix.identity(ti.f32, 3))             @ F_p.transpose()

    return stress

corotated.content:
def make_stress(P):
    """Corotated linear elasticity via the polar decomposition."""
    import taichi as ti

    @ti.func
    def stress(F_p):
        U, sig, V = ti.svd(F_p)
        # ti.svd returns F = U @ sig @ V^T with U, V merely orthogonal (det = +-1
        # each) -- fix reflections so U, V are proper rotations, else R = U @ V^T
        # would itself be an improper rotation (Sifakis & Barbic 2012, Sec 4).
        if U.determinant() < 0:
            for d in ti.static(range(3)):
                U[d, 2] = -U[d, 2]
            sig[2, 2] = -sig[2, 2]
        if V.determinant() < 0:
            for d in ti.static(range(3)):
                V[d, 2] = -V[d, 2]
            sig[2, 2] = -sig[2, 2]
        R = U @ V.transpose()
        J = ti.max(F_p.determinant(), 0.01)
        return 2.0 * P.mu * (F_p - R) @ F_p.transpose() + P.lam * (J - 1.0) * J             * ti.Matrix.identity(ti.f32, 3)

    return stress

