def make_stress(P):
    """Snow plasticity: clamped singular values + neo-Hookean stress."""
    import taichi as ti

    THETA_C = 0.025
    THETA_S = 0.0075

    @ti.func
    def stress(F_p):
        # ti.svd returns F = U @ sig @ V^T, so reconstruction needs V.transpose().
        U, sig, V = ti.svd(F_p)
        sig_c = ti.Matrix.identity(ti.f32, 3)
        for d in ti.static(range(3)):
            sig_c[d, d] = ti.min(ti.max(sig[d, d], 1.0 - THETA_C), 1.0 + THETA_S)
        F_hat = U @ sig_c @ V.transpose()
        J = ti.max(F_hat.determinant(), 0.01)
        return P.mu * (F_hat @ F_hat.transpose() - ti.Matrix.identity(ti.f32, 3))             + P.lam * ti.log(J) * ti.Matrix.identity(ti.f32, 3)

    return stress

