def make_project(x, edges, rest, inv_mass, dt):
    """Plain PBD: full projection to the rest length."""
    import taichi as ti

    @ti.kernel
    def project():
        for e in edges:
            a, b = edges[e][0], edges[e][1]
            wa, wb = inv_mass[a], inv_mass[b]
            if wa + wb == 0.0:
                continue
            rel = x[a] - x[b]
            d = rel.norm()
            if d < 1e-9:
                continue
            corr = (d - rest[e]) / (wa + wb) * rel / d
            x[a] -= wa * corr
            x[b] += wb * corr

    return project

