delayed_scaling.content:
class FP8Policy:
    """Per-tensor delayed scaling from a 16-entry amax history."""

    def __init__(self):
        self.history_len = 16
        self.histories = {}

    def granularity(self, role, layer_name):
        return 'tensor'

    def fp8_format(self, role):
        return 'e5m2' if role == 'grad' else 'e4m3'

    def scale(self, t, role, layer_name):
        fp8_max = 448.0 if self.fp8_format(role) == 'e4m3' else 57344.0
        key = (layer_name, role)
        hist = self.histories.setdefault(key, [])
        amax_now = t.detach().abs().amax().float()
        # Use the max over PREVIOUS steps (delayed); fall back to current
        # amax on the very first call for this operand. Everything stays on
        # device -- no .item()/float() on the hot path.
        amax = torch.stack(hist).amax() if hist else amax_now
        hist.append(amax_now)
        if len(hist) > self.history_len:
            hist.pop(0)
        return (amax.clamp(min=1e-12) / fp8_max).reshape(1)

    def keep_high_precision(self, layer_name):
        return False

