class WeightAverager:
    """EMA of the weights with fixed decay alpha=0.999."""

    def __init__(self, model, max_iters):
        self.alpha = 0.999
        self.avg = {k: v.detach().clone().float()
                    for k, v in model.state_dict().items()}
        self.saved = None

    def update(self, model, step):
        with torch.no_grad():
            for k, v in model.state_dict().items():
                self.avg[k].mul_(self.alpha).add_(v.float(), alpha=1 - self.alpha)

    def apply(self, model):
        self.saved = {k: v.detach().clone()
                      for k, v in model.state_dict().items()}
        model.load_state_dict({k: v.to(dtype=self.saved[k].dtype)
                               for k, v in self.avg.items()})

    def restore(self, model):
        if self.saved is not None:
            model.load_state_dict(self.saved)
            self.saved = None

