class WeightAverager:
    """Uniform average of the last 25% of iterates (SWA)."""

    def __init__(self, model, max_iters):
        self.start = int(0.75 * max_iters)
        self.count = 0
        self.avg = None
        self.saved = None

    def update(self, model, step):
        if step < self.start:
            return
        with torch.no_grad():
            sd = model.state_dict()
            if self.avg is None:
                self.avg = {k: v.detach().clone().float() for k, v in sd.items()}
                self.count = 1
                return
            self.count += 1
            for k, v in sd.items():
                self.avg[k].add_((v.float() - self.avg[k]) / self.count)

    def apply(self, model):
        self.saved = {k: v.detach().clone()
                      for k, v in model.state_dict().items()}
        if self.avg is not None:
            model.load_state_dict({k: v.to(dtype=self.saved[k].dtype)
                                   for k, v in self.avg.items()})

    def restore(self, model):
        if self.saved is not None:
            model.load_state_dict(self.saved)
            self.saved = None

lawa.content:
class WeightAverager:
    """Uniform average of the last k=5 checkpoints (every 500 steps)."""

    def __init__(self, model, max_iters):
        self.k = 5
        self.interval = 500
        self.max_iters = max_iters
        self.ckpts = []          # CPU float32 snapshots, newest last
        self.saved = None

    def _snapshot(self, model):
        snap = {k: v.detach().float().cpu().clone()
                for k, v in model.state_dict().items()}
        self.ckpts.append(snap)
        if len(self.ckpts) > self.k:
            self.ckpts.pop(0)

    def update(self, model, step):
        # Strictly every `interval` steps. An extra final snapshot at
        # step == max_iters would make the newest two checkpoints 35 steps
        # apart instead of 500, i.e. the average would no longer be over
        # k evenly spaced iterates, which is the whole construction.
        if step % self.interval == 0:
            self._snapshot(model)

    def apply(self, model):
        self.saved = {k: v.detach().clone()
                      for k, v in model.state_dict().items()}
        if not self.ckpts:
            return
        with torch.no_grad():
            avg = {k: torch.zeros_like(v) for k, v in self.ckpts[0].items()}
            for snap in self.ckpts:
                for k, v in snap.items():
                    avg[k].add_(v, alpha=1.0 / len(self.ckpts))
            model.load_state_dict(
                {k: v.to(device=self.saved[k].device,
                         dtype=self.saved[k].dtype) for k, v in avg.items()})

    def restore(self, model):
        if self.saved is not None:
            model.load_state_dict(self.saved)
            self.saved = None

