def custom_loss_func(
    outputs,
    labels,
    num_items_in_batch=None,
):
    """Standard token-level cross-entropy with causal shift."""
    logits = outputs.get("logits")
    if logits is None:
        return outputs.get("loss", torch.tensor(0.0))

    logits = logits.float()
    vocab_size = logits.size(-1)

    # Causal shift: logits[..., :-1, :] predicts labels[..., 1:]
    shift_logits = logits[..., :-1, :].contiguous().view(-1, vocab_size)
    shift_labels = labels[..., 1:].contiguous().view(-1).to(shift_logits.device)
    valid_mask = shift_labels != IGNORE_INDEX
    if not valid_mask.any():
        return shift_logits.sum() * 0.0

    loss_sum = F.cross_entropy(
        shift_logits, shift_labels, ignore_index=IGNORE_INDEX, reduction="sum"
    )

    if num_items_in_batch is not None:
        denom = num_items_in_batch
        if torch.is_tensor(denom):
            denom = denom.to(loss_sum.device)
        return loss_sum / denom
    return loss_sum / valid_mask.sum()

