# Agent (FIXED)
# ============================================================================


class OfflineRLAgent(flax.struct.PyTreeNode):
    rng: Any
    network: Any
    config: Any = nonpytree_field()

    def critic_loss(self, batch, grad_params, rng):
        """Fixed critic loss: standard TD learning with target network.

        The Bellman *target* is the policy's to define -- IQL's is an in-sample
        expectile value and ReBRAC's carries a next-action behaviour penalty,
        and neither is a property of the critic -- so PolicyTrainer may supply
        it. The default below (bootstrap from the current policy) is FQL's
        convention and is what a trainer that returns None gets.
        """
        rng, sample_rng = jax.random.split(rng)
        next_q = PolicyTrainer.critic_target_values(
            self.network, batch, self.config, sample_rng
        )
        if next_q is None:
            next_actions = PolicyTrainer.sample_actions(
                self.network, batch['next_observations'], self.config, sample_rng, temperature=0.0
            )
            next_actions = jnp.clip(next_actions, -1, 1)
            next_qs = self.network.select('target_critic')(batch['next_observations'], actions=next_actions)
            if self.config.get('q_agg', 'mean') == 'min':
                next_q = next_qs.min(axis=0)
            else:
                next_q = next_qs.mean(axis=0)
        target_q = batch['rewards'] + self.config['discount'] * batch['masks'] * next_q
        q = self.network.select('critic')(batch['observations'], actions=batch['actions'], params=grad_params)
        critic_loss = jnp.square(q - target_q).mean()
        return critic_loss, {
            'critic_loss': critic_loss,
            'q_mean': q.mean(),
            'q_max': q.max(),
            'q_min': q.min(),
        }

    @jax.jit
    def total_loss(self, batch, grad_params, rng=None):
        info = {}
        rng = rng if rng is not None else self.rng
        rng, actor_rng, critic_rng = jax.random.split(rng, 3)

        critic_loss, critic_info = self.critic_loss(batch, grad_params, critic_rng)
        for k, v in critic_info.items():
            info[f'critic/{k}'] = v

        # The critic is FIXED, and that has to hold against the actor loss too.
        # Handing the whole of grad_params to compute_actor_loss makes every
        # `network.select('critic')(...)` inside it differentiable, so a policy
        # whose objective contains -Q(s, pi(s)) -- FQL, ReBRAC, DDPG+BC, most of
        # what an agent would write -- also descends on the critic's own
        # parameters, and can raise its own Q instead of its own actions.
        # Reference FQL does not do this: agents/fql.py:70 evaluates the critic
        # with the frozen params, not grad_params. Freeze the critic subtrees
        # here so the editable surface cannot reach them, whatever it writes.
        _frozen = ('modules_critic', 'modules_target_critic')
        actor_params = {
            k: (jax.lax.stop_gradient(v) if k in _frozen else v)
            for k, v in grad_params.items()
        }
        actor_loss, actor_info = PolicyTrainer.compute_actor_loss(
            self.network.replace(params=actor_params), batch, self.config, actor_rng
        )
        for k, v in actor_info.items():
            info[f'actor/{k}'] = v

        loss = critic_loss + actor_loss
        return loss, info

    def target_update(self, network, module_name):
        new_target_params = jax.tree_util.tree_map(
            lambda p, tp: p * self.config['tau'] + tp * (1 - self.config['tau']),
            self.network.params[f'modules_{module_name}'],
            self.network.params[f'modules_target_{module_name}'],
        )
        network.params[f'modules_target_{module_name}'] = new_target_params

    @jax.jit
    def update(self, batch):
        new_rng, rng = jax.random.split(self.rng)

        def loss_fn(grad_params):
            return self.total_loss(batch, grad_params, rng=rng)

        new_network, info = self.network.apply_loss_fn(loss_fn=loss_fn)
        self.target_update(new_network, 'critic')
        for mod in PolicyTrainer.get_target_update_modules():
            self.target_update(new_network, mod)
        return self.replace(network=new_network, rng=new_rng), info

    @jax.jit
    def sample_actions(self, observations, seed=None, temperature=1.0):
        return PolicyTrainer.sample_actions(self.network, observations, self.config, seed, temperature)

    @classmethod
    def create(cls, seed, ex_observations, ex_actions, config):
        rng = jax.random.PRNGKey(seed)
        rng, init_rng = jax.random.split(rng, 2)

        action_dim = ex_actions.shape[-1]
        obs_dim = ex_observations.shape[-1]
        ex_times = ex_actions[..., :1]

        # Fixed critic networks.
        critic_def = Value(
            hidden_dims=config['value_hidden_dims'],
            layer_norm=config['layer_norm'],
            num_ensembles=2,
        )

        network_info = dict(
            critic=(critic_def, (ex_observations, ex_actions)),
            target_critic=(copy.deepcopy(critic_def), (ex_observations, ex_actions)),
        )

        # Add policy networks from PolicyTrainer.
        policy_nets = PolicyTrainer.create_policy_networks(
            obs_dim, action_dim, config['actor_hidden_dims'], config.get('actor_layer_norm', False)
        )
        # The critic is FIXED, so the editable surface must not be able to
        # supply a module under its name: dict.update would silently replace
        # the definition built above, and the stop_gradient in total_loss keys
        # off exactly these names.
        _reserved = {'critic', 'target_critic'}
        _clash = _reserved & set(policy_nets)
        assert not _clash, (
            f"create_policy_networks returned reserved module name(s) {sorted(_clash)}; "
            f"the critic is fixed and cannot be redefined."
        )
        network_info.update(policy_nets)

        # Add target networks for policy modules that need them.
        for mod in PolicyTrainer.get_target_update_modules():
            if mod in policy_nets:
                network_info[f'target_{mod}'] = (copy.deepcopy(policy_nets[mod][0]), policy_nets[mod][1])

        networks = {k: v[0] for k, v in network_info.items()}
        network_args = {k: v[1] for k, v in network_info.items()}

        network_def = ModuleDict(networks)
        network_tx = optax.adam(learning_rate=config['lr'])
        network_params = network_def.init(init_rng, **network_args)['params']
        network = TrainState.create(network_def, network_params, tx=network_tx)

        params = network.params
        params['modules_target_critic'] = params['modules_critic']
        for mod in PolicyTrainer.get_target_update_modules():
            params[f'modules_target_{mod}'] = params[f'modules_{mod}']

        config['obs_dim'] = obs_dim
        config['action_dim'] = action_dim
        return cls(rng, network=network, config=flax.core.FrozenDict(**config))


# ============================================================================
# Training loop (FIXED)
# ============================================================================


def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--env_name', type=str, required=True)
    parser.add_argument('--seed', type=int, default=0)
    parser.add_argument('--offline_steps', type=int, default=1000000)
    parser.add_argument('--eval_interval', type=int, default=100000)
    parser.add_argument('--eval_episodes', type=int, default=50)
    parser.add_argument('--log_interval', type=int, default=5000)
    parser.add_argument('--lr', type=float, default=3e-4)
    parser.add_argument('--batch_size', type=int, default=256)
    parser.add_argument('--discount', type=float, default=0.99)
    parser.add_argument('--tau', type=float, default=0.005)
    parser.add_argument('--alpha', type=float, default=10.0)
    parser.add_argument('--q_agg', type=str, default='mean')
    parser.add_argument('--normalize_q_loss', action='store_true', default=False)
    args = parser.parse_args()

    # Set up environment.
    env, eval_env, train_dataset, val_dataset = make_env_and_datasets(args.env_name)
    if PolicyTrainer.needs_next_actions():
        train_dataset.return_next_actions = True

    # Set seeds.
    import random
    random.seed(args.seed)
    np.random.seed(args.seed)

    # Config dict.
    config = dict(
        lr=args.lr,
        batch_size=args.batch_size,
        discount=args.discount,
        tau=args.tau,
        alpha=args.alpha,
        q_agg=args.q_agg,
        normalize_q_loss=args.normalize_q_loss,
        value_hidden_dims=(512, 512, 512, 512),
        actor_hidden_dims=(512, 512, 512, 512),
        layer_norm=True,
        actor_layer_norm=False,
    )

    # Create agent.
    example_batch = train_dataset.sample(1)
    agent = OfflineRLAgent.create(
        args.seed,
        example_batch['observations'],
        example_batch['actions'],
        config,
    )

    # Train.
    first_time = time.time()
    last_time = time.time()

    for i in tqdm(range(1, args.offline_steps + 1), smoothing=0.1, dynamic_ncols=True):
        batch = train_dataset.sample(config['batch_size'])
        agent, update_info = agent.update(batch)

        if i % args.log_interval == 0:
            elapsed = time.time() - first_time
            step_time = (time.time() - last_time) / args.log_interval
            last_time = time.time()
            critic_loss = float(update_info.get('critic/critic_loss', 0))
            q_mean = float(update_info.get('critic/q_mean', 0))
            actor_loss = float(update_info.get('actor/actor_loss', 0))
            print(f"TRAIN_METRICS step={i} critic_loss={critic_loss:.4f} q_mean={q_mean:.4f} "
                  f"actor_loss={actor_loss:.4f} step_time={step_time:.4f} elapsed={elapsed:.1f}",
                  flush=True)

        if args.eval_interval != 0 and (i == 1 or i % args.eval_interval == 0):
            eval_stats = evaluate(
                agent=agent,
                env=eval_env,
                policy_fn=agent.sample_actions,
                num_eval_episodes=args.eval_episodes,
                eval_temperature=0,
            )
            success = float(eval_stats.get('success', 0.0))
            print(f"TEST_METRICS step={i} success_rate={success:.4f}", flush=True)

    # Final evaluation.
    eval_stats = evaluate(
        agent=agent,
        env=eval_env,
        policy_fn=agent.sample_actions,
        num_eval_episodes=args.eval_episodes,
        eval_temperature=0,
    )
    success = float(eval_stats.get('success', 0.0))
    print(f"TEST_METRICS step={args.offline_steps} success_rate={success:.4f}", flush=True)
    # Persist the final success rate so the run script can re-emit the
    # authoritative final line AFTER this process exits (the parser is
    # last-match-wins; an in-process print, incl. atexit, can no longer
    # outrank it).
    _score_file = os.environ.get('FINAL_SCORE_FILE')
    if _score_file:
        with open(_score_file + '.tmp', 'w') as _f:
            _f.write(f"step={args.offline_steps} success_rate={success:.4f}\n")
        os.replace(_score_file + '.tmp', _score_file)
    print(f"Total training time: {time.time() - first_time:.1f}s", flush=True)


if __name__ == '__main__':
    main()

