class CustomMixer(nn.Module):
    """Single-layer LSTM mixer with an explicit carried (h, c) state."""

    def __init__(self, d_model: int, seq_len: int):
        super().__init__()
        self.d_model = d_model
        self.lstm = nn.LSTM(
            input_size=d_model,
            hidden_size=d_model,
            num_layers=1,
            batch_first=True,
        )
        self.out_proj = nn.Linear(d_model, d_model, bias=False)

    def init_state(self, batch: int, device):
        h = torch.zeros(1, batch, self.d_model, device=device)
        c = torch.zeros(1, batch, self.d_model, device=device)
        return (h, c)

    def step(self, x_chunk: torch.Tensor, state):
        y, new_state = self.lstm(x_chunk, state)
        return self.out_proj(y), new_state

