def build_positional_scheme(config: TaskConfig) -> PositionalScheme:
    """Rotary position embeddings (RoPE), applied to q/k inside attention."""
    head_dim = config.d_model // config.n_heads
    assert head_dim % 2 == 0
    inv_freq = 1.0 / (
        10000.0 ** (torch.arange(0, head_dim, 2, dtype=torch.float32) / head_dim)
    )

    def _rotate_half(x: torch.Tensor) -> torch.Tensor:
        x1, x2 = x.chunk(2, dim=-1)
        return torch.cat([-x2, x1], dim=-1)

    def rotary(q: torch.Tensor, k: torch.Tensor):
        # q, k: [B, H, T, head_dim]
        T = q.shape[-2]
        freqs = torch.outer(
            torch.arange(T, device=q.device, dtype=torch.float32),
            inv_freq.to(q.device),
        )
        emb = torch.cat([freqs, freqs], dim=-1)          # [T, head_dim]
        cos = emb.cos().to(q.dtype)
        sin = emb.sin().to(q.dtype)
        q_rot = q * cos + _rotate_half(q) * sin
        k_rot = k * cos + _rotate_half(k) * sin
        return q_rot, k_rot

    return PositionalScheme(
        name="rotary",
        token_embedding_extra=None,
        attn_bias=None,
        rotary=rotary,
        extra_modules=nn.ModuleList(),
    )


def build_model(config: TaskConfig) -> nn.Module:
    scheme = build_positional_scheme(config)
    return SeqModel(config, scheme, use_lstm=False)

