def build_model(config: TaskConfig) -> nn.Module:
    """Two-layer mean-field network (Abbe et al. Fig. 1 architecture)."""

    class TwoLayerMeanField(nn.Module):
        def __init__(self, d: int, M: int) -> None:
            super().__init__()
            self.fc1 = nn.Linear(d, M, bias=False)
            self.fc2 = nn.Linear(M, 1, bias=False)
            nn.init.normal_(self.fc1.weight, mean=0.0, std=1.0)
            with torch.no_grad():
                signs = torch.randint(0, 2, (M, 1), dtype=torch.float32) * 2.0 - 1.0
                self.fc2.weight.copy_(signs.t())
            self.M = M

        @staticmethod
        def _shifted_sigmoid(u: torch.Tensor) -> torch.Tensor:
            return torch.sigmoid(u - 0.5)

        def forward(self, x: torch.Tensor) -> torch.Tensor:
            h = self._shifted_sigmoid(self.fc1(x))
            return self.fc2(h).view(-1) / self.M

    return TwoLayerMeanField(d=config.d, M=config.width)


def get_optimizer(model: nn.Module, config: TaskConfig) -> torch.optim.Optimizer:
    """Width-corrected mean-field step sizes (see mean_field_sgd)."""
    groups = [
        {"params": model.fc1.parameters(), "lr": 0.5 * config.width},
        {"params": model.fc2.parameters(), "lr": 0.5},
    ]
    return torch.optim.SGD(groups, momentum=0.0)


_REUSE_T = 2  # gradient steps per batch (Dandi et al. 2024 use T = 2)


def train_step(
    model: nn.Module,
    optimizer: torch.optim.Optimizer,
    x: torch.Tensor,
    y: torch.Tensor,
) -> float:
    """REUSE_T consecutive SGD updates on the SAME fresh batch (x, y).

    Reusing a batch implements the non-correlational queries that one-pass
    SGD lacks (Dandi et al. 2024): the second update correlates functions
    of the CURRENT weights with the SAME data, breaking the information-
    exponent barrier of pure online SGD.
    """
    first_loss = None
    for _ in range(_REUSE_T):
        optimizer.zero_grad(set_to_none=True)
        pred = model(x).view(-1)
        loss = ((pred - y) ** 2).mean()
        if first_loss is None:
            first_loss = float(loss.item())
        loss.backward()
        optimizer.step()
    return first_loss

